def once(old: str, new: str, label: str):
    global text
    n = text.count(old)
    if n != 1:
        raise ValueError(f'{label}: expected one match, found {n}: {old[:120]!r}')
    text = text.replace(old, new, 1)

def many(old: str, new: str, expected_min: int, label: str):
    global text
    n = text.count(old)
    if n < expected_min:
        raise ValueError(f'{label}: expected at least {expected_min}, found {n}: {old[:120]!r}')
    text = text.replace(old, new)
    print(f'{label}: {n} replacements')

def first(old: str, new: str, label: str):
    global text
    n = text.count(old)
    if n < 1:
        raise ValueError(f'{label}: expected at least one match, found 0: {old[:120]!r}')
    text = text.replace(old, new, 1)

